using System.ClientModel;
using Azure.AI.OpenAI;
using Azure.Identity;
using OpenAI;

namespace MyApp.Evals.Tests;

/// <summary>
/// Resolves the same IChatClient the app uses, by building an Azure OpenAI
/// client from the connection string.
/// Detected: AddAzureOpenAIChatClient("chat", "gpt-4o-mini") at AppHost.cs:1
/// </summary>
internal static class AgentChatClientFactory
{
    private const string ConnectionStringName = "chat";
    private const string DefaultDeployment = "gpt-4o-mini";

    public static IChatClient Create(string? deploymentOverride = null)
    {
        var builder = Host.CreateApplicationBuilder();
        builder.Configuration.AddUserSecrets(typeof(AgentChatClientFactory).Assembly, optional: true);
        var config = builder.Build().Services.GetRequiredService<IConfiguration>();

        var connStr = config.GetConnectionString(ConnectionStringName);
        if (string.IsNullOrEmpty(connStr))
        {
            throw new InvalidOperationException(
                $"EVAL_USE_REAL_AGENT=1 but connection string \"{ConnectionStringName}\" is not configured. " +
                "The detected registration (AddAzureOpenAIChatClient) reads connection " +
                $"string \"{ConnectionStringName}\" from configuration. Aspire's AppHost " +
                "populates this at runtime, but `dotnet test` runs standalone. " +
                "Wire one of:\n" +
                $"  dotnet user-secrets init --project MyApp.Evals.Tests\n" +
                $"  # Key-based auth:\n" +
                $"  dotnet user-secrets set \"ConnectionStrings:{ConnectionStringName}\" " +
                $"\"Endpoint=https://<host>.services.ai.azure.com/models;Key=<key>;DeploymentId={ConnectionStringName}\" --project MyApp.Evals.Tests\n" +
                $"  # Entra-ID auth (DefaultAzureCredential):\n" +
                $"  dotnet user-secrets set \"ConnectionStrings:{ConnectionStringName}\" " +
                $"\"Endpoint=https://<host>.services.ai.azure.com/models;DeploymentId={ConnectionStringName}\" --project MyApp.Evals.Tests\n" +
                "Note: the hostname strips dashes from the resource name " +
                "(resource `foundry-abc` -> host `foundryabc.services.ai.azure.com`).");
        }

        var deployment = deploymentOverride ?? DefaultDeployment;
        var parts = ParseConnectionString(connStr);

        var endpoint = parts.GetValueOrDefault("Endpoint")
            ?? throw new InvalidOperationException("Connection string missing 'Endpoint'.");
        var key = parts.GetValueOrDefault("Key");
        var deployId = parts.GetValueOrDefault("DeploymentId") ?? deployment;

        OpenAIClient client;
        if (!string.IsNullOrEmpty(key))
            client = new AzureOpenAIClient(new Uri(endpoint), new ApiKeyCredential(key));
        else
            client = new AzureOpenAIClient(new Uri(endpoint), new DefaultAzureCredential());

        return client.GetChatClient(deployId).AsIChatClient();
    }

    private static Dictionary<string, string> ParseConnectionString(string connStr)
    {
        var result = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        foreach (var part in connStr.Split(';', StringSplitOptions.RemoveEmptyEntries))
        {
            var eq = part.IndexOf('=');
            if (eq > 0)
                result[part[..eq].Trim()] = part[(eq + 1)..].Trim();
        }
        return result;
    }
}

