    {
        // Override: judge uses a different deployment than the agent
        var builder = Host.CreateApplicationBuilder();
        builder.Configuration.AddUserSecrets(typeof(AgentChatClientFactory).Assembly, optional: true);
        builder.AddAzureOpenAIChatClient("chat", judgeDeployment);
        return builder.Build().Services.GetRequiredService<IChatClient>();
    }
    // Default: same client serves both agent and judge (cache benefits both)
    return agentClient;
