public static IChatClient ResolveJudgeClient(IChatClient agentClient)
{
    var judgeDeployment = Environment.GetEnvironmentVariable("EVAL_JUDGE_DEPLOYMENT_NAME");
    if (!string.IsNullOrEmpty(judgeDeployment))
    {
        // Override: judge uses a different deployment than the agent
        return AgentChatClientFactory.Create(deploymentOverride: judgeDeployment);
    }
    // Default: same client serves both agent and judge (cache benefits both)
    return agentClient;
}

